class Solution:
    def findMaximalUncoveredRanges(self, n: int, ranges: List[List[int]]) -> List[List[int]]:
        ranges.sort()
        res = []
        cur = 0
        for l, r in ranges:
            if l > cur:
                res.append([cur, l - 1])
            cur = max(cur, r + 1)
        if cur < n:
            res.append([cur, n - 1])
        return res

