class Solution {
public:
    vector<vector<int>> findMaximalUncoveredRanges(int n, vector<vector<int>>& ranges) {
        sort(ranges.begin(), ranges.end());
        vector<vector<int>> res;
        long long cur = 0;
        for (auto& rg : ranges) {
            if (rg[0] > cur) res.push_back({(int)cur, rg[0] - 1});
            cur = max(cur, (long long)rg[1] + 1);
        }
        if (cur < n) res.push_back({(int)cur, n - 1});
        return res;
    }
};

