var findMaximalUncoveredRanges = function(n, ranges) {
    ranges.sort((a, b) => a[0] - b[0]);
    const res = [];
    let cur = 0;
    for (const [l, r] of ranges) {
        if (l > cur) res.push([cur, l - 1]);
        cur = Math.max(cur, r + 1);
    }
    if (cur < n) res.push([cur, n - 1]);
    return res;
};
